t, effect)\n    effect:addMod(xi.mod.STR, 4)\n    effect:addMod(xi.mod.INT, -6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/slime_cap.lua"]={["Path"]="scripts/items/slime_cap.lua",["SHA256"]="96a8bddacd64a0e0559d777c0c7852b3d8271f03563648b43b4c70cfdf7ca4cc",["Text"]="-----------------------------------\n-- ID: 27756\n-- Item: Slime Cap\n-- Dispense: Slimeulation Candy\n-- TODO: Add hidden set effect\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.SLIMEULATION_CANDY, math.randomInt(5, 12) } })\nend\n\nreturn itemObject\n"},["scripts/items/slime_rocket.lua"]={["Path"]="scripts/items/slime_rocket.lua",["SHA256"]="bdb915a6828f256c30e6513c3c032f4d85613eb091bed3f8a0a574b5d56fb265",["Text"]="-----------------------------------\n-- ID: 6186\n-- Slime Rocket\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/smash_cesti.lua"]={["Path"]="scripts/items/smash_cesti.lua",["SHA256"]="50c9fe6b4cabce43d0ecb27a4afe6a9e39d46662b7262841479843ecd09dd888",["Text"]="-----------------------------------\n-- ID: 18747\n-- Item: smash_cesti\n-- Item Effect: Attack +3\n-- Duration: 30 Minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.SMASH_CESTI) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.SMASH_CESTI)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.SMASH_CESTI) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.SMASH_CESTI })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.ATT, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/smilodon_liver.lua"]={["Path"]="scripts/items/smilodon_liver.lua",["SHA256"]="e76ad23e05a06d4e177c791972acc118ab686c21271109788cde2855db648db1",["Text"]="-----------------------------------\n-- ID: 5668\n-- Item: Smilodon Liver\n-- Food Effect: 5Min, Galka only\n-----------------------------------\n-- Strength 5\n-- Intelligence -7\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_MEAT)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 5)\n    effect:addMod(xi.mod.INT, -7)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/smoked_salmon.lua"]={["Path"]="scripts/items/smoked_salmon.lua",["SHA256"]="3c156612b0383f0a21d12f6f6e6778d8d3d2138c0b9cba92a9160fb2cbe5df72",["Text"]="-----------------------------------\n-- ID: 4380\n-- Item: smoked_salmon\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Dexterity 2\n-- Mind -3\n-- Ranged Accuracy +1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -3)\n    effect:addMod(xi.mod.RACC, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/smoldering_salisbury_steak.lua"]={["Path"]="scripts/items/smoldering_salisbury_steak.lua",["SHA256"]="50dff630d74eb947555f602b88fbd3be04083fff48ac68048ee435e481aed891",["Text"]="-----------------------------------\n-- ID: 5924\n-- Item: Smoldering Salisbury Steak\n-- Food Effect: 180 Min, All Races\n-----------------------------------\n-- HP +30\n-- Strength +7\n-- Intelligence -5\n-- Attack % 20 Cap 160\n-- Ranged Attack %20 Cap 160\n-- Dragon Killer +5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 30)\n    effect:addMod(xi.mod.STR, 7)\n    effect:addMod(xi.mod.INT, -5)\n    effect:addMod(xi.mod.FOOD_ATTP, 20)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 160)\n    effect:addMod(xi.mod.FOOD_RATTP, 20)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 160)\n    effect:addMod(xi.mod.DRAGON_KILLER, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/sneaking_boots.lua"]={["Path"]="scripts/items/sneaking_boots.lua",["SHA256"]="25ee31841398b4625e408b1debeb7d9a0cc93a74d83320cd01f4a0fb51a77a35",["Text"]="-----------------------------------\n--  ID: 15698\n--  Sneaking Boots\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:delStatusEffect(xi.effect.SNEAK)\n    target:addStatusEffect(xi.effect.SNEAK, { power = 1, duration = math.floor(180 * xi.settings.main.SNEAK_INVIS_DURATION_MULTIPLIER), origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/snow_bunny_hat_+1.lua"]={["Path"]="scripts/items/snow_bunny_hat_+1.lua",["SHA256"]="14c6370482cf84ef8539e4e98a60e2fa035f0455cfd91fefe1584c7293111087",["Text"]="-----------------------------------\n-- ID: 11491\n-- Snow bunny Hat +1\n-- Enchantment: 60Min, Costume - White Rarab\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 270, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/snowman_cap.lua"]={["Path"]="scripts/items/snowman_cap.lua",["SHA256"]="7eafef358bf729bbacbbae3034a2d915e7d5be33cb5fb779e1bc99086c097dd3",["Text"]="-----------------------------------\n-- ID: 10875\n-- Snowman Cap\n-- Enchantment: 60Min, Costume - Snoll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 279, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/sobbing_fungus.lua"]={["Path"]="scripts/items/sobbing_fungus.lua",["SHA256"]="819184021c5fa0a5c4ce58ebe12f45793e52e3f47107a7e3a2f20da7e8eddade",["Text"]="-----------------------------------\n-- ID: 4565\n-- Item: Sobbing Fungus\n-- Food Effect: 3 Mins, All Races\n-- Silence\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 180, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\n    if not target:hasStatusEffect(xi.effect.SILENCE) then\n        target:addStatusEffect(xi.effect.SILENCE, { power = 1, duration = 180, origin = user, tick = 3 })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/soft-boiled_egg.lua"]={["Path"]="scripts/items/soft-boiled_egg.lua",["SHA256"]="2b1f04863764893eb68b1b7cc52d7c8a3ebf98ea6be0aa17c9cfeec96184ca36",["Text"]="-----------------------------------\n-- ID: 4532\n-- Item: soft-boiled_egg\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Health 20\n-- Magic 20\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 20)\n    effect:addMod(xi.mod.FOOD_MP, 20)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/sonic_knuckles.lua"]={["Path"]="scripts/items/sonic_knuckles.lua",["SHA256"]="014310827d7e844b23a431f494b2196fbe4931fcf30bbe764e3e1939c5dd4fdd",["Text"]="-----------------------------------\n-- ID: 16434\n-- Item: Sonic Knuckles\n-- Additional effect: wind damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 5,\n        basePower      = math.randomInt(6, 8),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WIND,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/soothing_potion.lua"]={["Path"]="scripts/items/soothing_potion.lua",["SHA256"]="8280da7dcd22f8b08d189881ef0072cacd806af92359d78fd0910cb94f84ea8c",["Text"]="-----------------------------------\n-- ID: 4125\n-- Item: Soothing Potion\n-- Item Effect: Restores 250 HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getHP() == target:getMaxHP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, target:addHP(250 * xi.settings.main.ITEM_POWER))\nend\n\nreturn itemObject\n"},["scripts/items/soultrapper.lua"]={["Path"]="scripts/items/soultrapper.lua",["SHA256"]="c279c0d13cf6b0b930a148a942805f40b0c9aa77942fbb1901992f42cc5f8d11",["Text"]="-----------------------------------\n-- Soultrapper (18724)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.znm.soultrapper.onItemCheck(target, item, caster)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    xi.znm.soultrapper.onItemUse(target, user, item)\nend\n\nreturn itemObject\n"},["scripts/items/soultrapper_2000.lua"]={["Path"]="scripts/items/soultrapper_2000.lua",["SHA256"]="ae4ba08256ee0891a2b63dd401ad19e736c5093085e76190e75cdd34758428cd",["Text"]="-----------------------------------\n-- Soultrapper (18721)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.znm.soultrapper.onItemCheck(target, item, caster)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    xi.znm.soultrapper.onItemUse(target, user, item)\nend\n\nreturn itemObject\n"},["scripts/items/spark_baselard.lua"]={["Path"]="scripts/items/spark_baselard.lua",["SHA256"]="8adb001d901ad479aa039868ee5033976e875202bc71fae050fe381e066be1d7",["Text"]="-----------------------------------\n-- ID: 17986\n-- Item: Spark Baselard\n-- Additional effect: lightning damage depending on ammo\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local damageRange = xi.additionalEffect.getConsumableAmmoItemDamageRange(xi.element.THUNDER, actor:getEquipID(xi.slot.AMMO))\n\n    if not damageRange then\n        return 0, 0, 0\n    end\n\n    local pTable =\n    {\n        chance          = 10, -- TODO: get data on Daggers. This rate is from h2h (hydro patas)\n        basePower       = math.randomInt(damageRange[1], damageRange[2]),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.THUNDER,\n        canMAB          = false,\n        canResist       = true,\n        lowestResist    = 0.5,\n        useAmmo         = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/spark_baselard_+1.lua"]={["Path"]="scripts/items/spark_baselard_+1.lua",["SHA256"]="8a7d319c233d3bb16cb2420eb7beb